public class Rectangle {
    private int width;
    private int height;

    Rectangle(int width, int height) {
        this.width = width;
        this.height = height;
    }

    int getWidth() { return width; }
    int getHeight() { return height; }

    public static void main(String[] args) {
        Rectangle r = new Rectangle(4, 9);
        System.out.println(r.getHeight());
    }
}
